import {ToolRegistry} from './registry.js';

describe('ToolRegistry.execute', () => {
  it('returns a ToolResponse when a required property is absent, without calling the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'greet',
        description: 'greet',
        inputSchema: {type: 'object', properties: {name: {type: 'string'}}, required: ['name']},
      },
      async () => {
        executorCalls += 1;
        return 'hello';
      }
    );
    const response = await registry.execute('greet', {});
    expect({executorCalls, missingFieldNamed: response.result.includes('name')}).toEqual({
      executorCalls: 0,
      missingFieldNamed: true,
    });
  });
});

